define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_10.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e97337","topics":[]},{"title":"Removing the string encoder","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingTheStringEncoder.html","attributes":{"data-id":"id_2005769"},"menu":{"hasChildren":false},"tocID":"id_2005769-d46e97441","topics":[]},{"title":"Installing the string encoder","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_InstallingTheStringEncoder.html","attributes":{"data-id":"id_2005770"},"menu":{"hasChildren":false},"tocID":"id_2005770-d46e97544","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_14.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e97647","topics":[]},{"title":"Finalizing string encoder replacement","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_FinalizingStringEncoderReplacement.html","attributes":{"data-id":"id_2005771"},"menu":{"hasChildren":false},"tocID":"id_2005771-d46e97751","topics":[]},{"title":"Doing DQA calibration with the DQA III phantom","shortdesc":"<p class=\"shortdesc\">The DQA tool determines correct gradient polarity and correct gradient wiring by scanning a series of axial and coronal images of the DQA III phantom for systems below sentence MR 31.0 or sites that do not have a 17cm Sphere with Spout (SWS) phantom.<\/p>","href":"t_DoingDQACalibration_3.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e97855","topics":[]},{"title":"Doing DQA calibration <span class=\"ph\">with the Sphere With Spout (SWS) phantom<\/span>","shortdesc":"<p class=\"shortdesc\">Details the steps needed to run the Gradient Calibration Tool (GCT) for systems running MR31.0 and higher<span class=\"ph\"> and that possess the 17cm Sphere with Spout (SWS) phantom<\/span>. GCT does the same checks and produces the same output as DQA.<\/p>","href":"t_DoingDQACalibrationsforMR31andHigher_3.html","attributes":{"data-id":"id_2068424"},"menu":{"hasChildren":false},"tocID":"id_2068424-d46e97959","topics":[]},{"title":"Doing the cradle motion test","shortdesc":"<p class=\"shortdesc\">Makes sure the motion of the patient cradle into and out of the magnet bore is operating correctly.<\/p>","href":"t_CradleMotionTest_2.html","attributes":{"data-id":"id_2001666"},"menu":{"hasChildren":false},"tocID":"id_2001666-d46e98068","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_16.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e98172","topics":[]}]});